config.prompt:
Write a reply to this customer's email for the support team to send. Be warm and specific, answer what they asked, keep it under 150 words and sign off as "The support team". Do not promise refunds or dates. Personal data has been replaced with labels such as [REDACTED_EMAIL]: never fill them in or repeat them.

Category: {{ state.category }}
Order number: {{ state.order_number or state.details or "not given" }}

{{ state.message }}

files.events/schemas/support.email.received.js:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "support.email.received",
  "description": "An email arrived at the support address.",
  "type": "object",
  "required": [
    "message_id",
    "subject",
    "body"
  ],
  "properties": {
    "message_id": {
      "type": "string",
      "description": "The email's Message-ID, so a repeat starts nothing"
    },
    "from": {
      "type": "string",
      "description": "The sender's address"
    },
    "subject": {
      "type": "string"
    },
    "body": {
      "type": "string",
      "description": "The email's text"
    }
  }
}
